# Example of evaluating an arithmetic expression safely without using eval
def safe_eval(expr):
    allowed_operators = {'+', '-', '*', '/'}
    for char in expr:
        if not (char.isdigit() or char.isspace() or char in allowed_operators):
            raise ValueError("Invalid character in expression")
    return eval(expr, {"__builtins__": None}, {})

# Test the safe_eval function
try:
    print(safe_eval("1 + 2 * 3"))  # Expected output: 7
except ValueError as e:
    print(e)
